"""Compile reviewed translation-memory batches into the static Python catalog.

Usage: python .github/scripts/build_backend_text_catalog.py [translation-work-dir]
Only exact English source matches are merged. No runtime translation or file
loading is introduced into the integration by this build tool.
"""
from __future__ import annotations

import ast
import importlib
from itertools import combinations
import json
from pathlib import Path
import string
import sys
from types import ModuleType

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "custom_components/environment_manager"
WORK = Path(sys.argv[1]) if len(sys.argv) > 1 else None
LOCALIZATION = ROOT / ".github/localization"
LOCALIZATION.mkdir(parents=True, exist_ok=True)
if WORK is not None:
    requests = json.loads((WORK / "backend-text-requests.json").read_text())["requests"]
    memory = {item["en"]: {"en": item["en"], **item["existing"]} for item in requests}
else:
    memory = json.loads((LOCALIZATION / "backend_help.json").read_text())
required = set(memory)

def fields(value):
    return sorted({key for _, key, _, _ in string.Formatter().parse(value) if key is not None})

sources = [] if WORK is None else [
    WORK / "frontend-translation-memory.json",
    WORK / "native-root-prose-memory.json",
    WORK / "frontend-root-help-memory.json",
    *sorted(WORK.glob("backend-memory-*.json")),
]
# Exact reviewed variants take precedence over older translation memories.
# In particular, a generic form explanation must not replace the existing
# detailed German explanation when the same English source key is merged.
sources.append(LOCALIZATION / "backend_authoritative_variants.json")
for file in sources:
    if not file.is_file():
        continue
    values = json.loads(file.read_text())
    for english, translations in values.items():
        if english not in required or not isinstance(translations, dict):
            continue
        for locale, text in translations.items():
            if not isinstance(text, str) or not text.strip():
                continue
            if fields(english) != fields(text):
                raise ValueError(f"Placeholder mismatch in {file.name}: {locale}: {english}")
            memory[english][locale] = text

def write_atomic(path, contents):
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(contents)
    temporary.replace(path)


serialized = json.dumps(memory, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
# Do not pretty-print nested dictionaries below their English source key:
# a long paragraph would become the indentation of every translation line.
# Fixed indentation keeps the importable constant close to its source size.
lines = [
    '"""Static exact-source translations; generated by build_backend_text_catalog.py."""',
    "", "TEXT = {",
]
for english, variants in sorted(memory.items()):
    if not isinstance(english, str) or not isinstance(variants, dict):
        raise ValueError("Catalog sources must map strings to locale dictionaries")
    lines.append(f"    {english!r}: {{")
    for locale, value in sorted(variants.items()):
        if not isinstance(locale, str) or not isinstance(value, str) or not value.strip():
            raise ValueError(f"Invalid translation for {english!r}: {locale!r}")
        if fields(english) != fields(value):
            raise ValueError(f"Placeholder mismatch: {locale}: {english}")
        lines.append(f"        {locale!r}: {value!r},")
    lines.append("    },")
lines.append("}")
generated = "\n".join(lines) + "\n"
if len(generated.encode()) > 2 * len(serialized.encode()) + 65_536:
    raise ValueError("Generated catalog exceeds its source-size budget")
write_atomic(SOURCE / "backend_text_catalog.py", generated)
write_atomic(LOCALIZATION / "backend_help.json", serialized)
if WORK is not None:
    write_atomic(WORK / "backend-translation-memory.json", serialized)
print(f"Compiled {len(memory)} source messages / {sum(len(v) for v in memory.values())} language values")

# The card has its own UI language. Export the finite composed messages using
# the production assembly so it can resolve English entity metadata exactly.
# These combinations are not duplicated in the Python runtime catalog.
sys.dont_write_bytecode = True
package = ModuleType("hem_text_build")
package.__path__ = [str(SOURCE)]
sys.modules[package.__name__] = package
help_module = importlib.import_module(package.__name__ + ".equipment_help")
mode_module = importlib.import_module(package.__name__ + ".operating_mode_catalog")
text_module = importlib.import_module(package.__name__ + ".backend_text")
tree = ast.parse((SOURCE / "equipment_mode_entities.py").read_text())
nodes = [n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name in ("target_field", "scoped_help")]
profiles = next(ast.literal_eval(n.value) for n in tree.body if isinstance(n, ast.Assign)
                and any(isinstance(t, ast.Name) and t.id == "TARGET_PROFILES" for t in n.targets))
scope = {"TARGET_PROFILES": profiles, "mode_locale": mode_module.mode_locale,
         "translated_text": text_module.translated_text}
exec(compile(ast.Module(body=nodes, type_ignores=[]), str(SOURCE / "equipment_mode_entities.py"), "exec"), scope)
prefixes = [ast.literal_eval(n)["en"] for n in ast.walk(next(n for n in nodes if n.name == "scoped_help"))
            if isinstance(n, ast.Dict) and any(isinstance(k, ast.Constant) and k.value == "en" for k in n.keys)]
composed = {}

def export(render, dependencies):
    english = render("en")
    composed[english] = {
        locale: render(locale)
        for locale in text_module.SUPPORTED_LANGUAGE_TAGS
        if locale == "en" or all(locale in memory.get(source, {}) for source in dependencies)
    }

for count in range(1, 5):
    for modes in combinations(("heat", "cool", "dry", "humidify"), count):
        dependencies = [help_module.HELP["native_full_output"][0],
                        *(help_module._NATIVE_MODE_TARGET_HELP[m][0] for m in modes)]
        export(lambda locale, modes=modes: help_module.equipment_configuration_help(
            "native_full_output", locale, modes=modes), dependencies)

for key in ("control_mode", "target_home_heat", "target_home_humidity"):
    ordinary = help_module.equipment_configuration_help(key, "en")
    english = scope["scoped_help"](key, "en", ordinary)
    dependencies = [source for source in prefixes if source in english]
    if ordinary in english:
        dependencies.append(ordinary)
    export(lambda locale, key=key: scope["scoped_help"](
        key, locale, help_module.equipment_configuration_help(key, locale)), dependencies)

serialized = json.dumps(composed, ensure_ascii=False, indent=2) + "\n"
write_atomic(LOCALIZATION / "backend_composed_help.json", serialized)
if WORK is not None:
    write_atomic(WORK / "backend-composed-help-memory.json", serialized)
print(f"Exported {len(composed)} composed help messages for the card")
